    73	    };
    74	    if (typeof message.content === "string") {
    75	      message.content = [{ type: "text", text: message.content }, block];
    76	    } else if (Array.isArray(message.content)) {
    77	      message.content.push(block);
    78	    } else {
    79	      return undefined;
    80	    }
    81	    return next;
    82	  }
